"""Image captcha generated by the portal itself. No outside service is called.

A challenge is stored with a hash of its answer, expires after a few minutes
and is deleted on the first attempt, right or wrong.
"""

import base64
import hashlib
import io
import logging
import secrets
import uuid
from datetime import UTC, datetime, timedelta

from PIL import Image, ImageDraw, ImageFont
from sqlalchemy import delete
from sqlalchemy.orm import Session

from app.core.config import get_settings
from app.models import Captcha
from app.services import settings as app_settings

logger = logging.getLogger(__name__)

# No 0/O, 1/I/L, 5/S, 2/Z, 8/B: easy to confuse in a distorted image.
_ALPHABET = "ACDEFGHJKMNPQRTUVWXY34679"
_LENGTH = 5
_WIDTH, _HEIGHT = 200, 70


def _hash(answer: str) -> str:
    return hashlib.sha256(answer.strip().upper().encode()).hexdigest()


def _render(text: str) -> bytes:
    rng = secrets.SystemRandom()
    image = Image.new("RGB", (_WIDTH, _HEIGHT), (246, 247, 249))
    draw = ImageDraw.Draw(image)

    for _ in range(6):
        draw.line(
            [
                (rng.randint(0, _WIDTH), rng.randint(0, _HEIGHT)),
                (rng.randint(0, _WIDTH), rng.randint(0, _HEIGHT)),
            ],
            fill=(rng.randint(140, 200), rng.randint(140, 200), rng.randint(140, 200)),
            width=2,
        )

    font = ImageFont.load_default(size=40)
    slot = (_WIDTH - 20) // len(text)
    for index, char in enumerate(text):
        glyph = Image.new("RGBA", (50, 60), (0, 0, 0, 0))
        ImageDraw.Draw(glyph).text(
            (8, 4),
            char,
            font=font,
            fill=(rng.randint(10, 90), rng.randint(10, 90), rng.randint(10, 90), 255),
        )
        glyph = glyph.rotate(rng.randint(-22, 22), resample=Image.Resampling.BICUBIC, expand=True)
        image.paste(glyph, (10 + index * slot + rng.randint(-3, 3), rng.randint(0, 10)), glyph)

    for _ in range(250):
        draw.point(
            (rng.randint(0, _WIDTH - 1), rng.randint(0, _HEIGHT - 1)),
            fill=(rng.randint(90, 180), rng.randint(90, 180), rng.randint(90, 180)),
        )

    buffer = io.BytesIO()
    image.save(buffer, format="PNG")
    return buffer.getvalue()


def create(db: Session) -> tuple[str, str, str]:
    """Create a challenge. Returns (captcha id, answer, PNG image as a data URL)."""
    now = datetime.now(UTC)
    db.execute(delete(Captcha).where(Captcha.expires_at < now))

    answer = "".join(secrets.choice(_ALPHABET) for _ in range(_LENGTH))
    captcha_id = str(uuid.uuid4())
    valid_minutes = app_settings.get_int(db, app_settings.CAPTCHA_VALID_MINUTES)
    db.add(
        Captcha(
            id=captcha_id,
            answer_hash=_hash(answer),
            expires_at=now + timedelta(minutes=valid_minutes),
        )
    )

    if not get_settings().is_production:
        # Development convenience, as for OTPs: never logged in production.
        logger.warning("DEV captcha %s answer: %s", captcha_id, answer)

    image = "data:image/png;base64," + base64.b64encode(_render(answer)).decode()
    return captcha_id, answer, image


def verify(db: Session, captcha_id: str | None, answer: str | None) -> bool:
    """Check an answer. The challenge is used up whatever the result."""
    if not captcha_id or not answer:
        return False
    captcha = db.get(Captcha, captcha_id)
    if captcha is None:
        return False
    db.delete(captcha)
    db.flush()
    if captcha.expires_at < datetime.now(UTC):
        return False
    return secrets.compare_digest(captcha.answer_hash, _hash(answer))
